using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Text.RegularExpressions;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;
public static class ENSurvey {
 static bool Korean(string s)=>Regex.IsMatch(s??"", "[\\u1100-\\u11ff\\u3130-\\u318f\\uac00-\\ud7af]");
 public static object Run(){if(Application.isPlaying||SceneManager.GetActiveScene().isDirty)throw new Exception("Saved edit mode required");string repo=Path.GetFullPath(Path.Combine(Application.dataPath,"../../..")),dir=repo+"/SourceAssets/EnglishNaming/";var setup=EditorSceneManager.GetSceneManagerSetup();var names=new List<object>();var scenes=new List<object>();
  try{foreach(string path in AssetDatabase.FindAssets("t:Scene",new[]{"Assets"}).Select(AssetDatabase.GUIDToAssetPath)){var s=EditorSceneManager.OpenScene(path,OpenSceneMode.Single);var ts=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var rows=new List<object>();foreach(var t in ts){var prefab=PrefabUtility.GetNearestPrefabInstanceRoot(t.gameObject);var row=new{id=GlobalObjectId.GetGlobalObjectIdSlow(t).ToString(),name=t.name,parent=t.parent?GlobalObjectId.GetGlobalObjectIdSlow(t.parent).ToString():null,position=new[]{t.position.x,t.position.y,t.position.z},rotation=new[]{t.rotation.x,t.rotation.y,t.rotation.z,t.rotation.w},scale=new[]{t.localScale.x,t.localScale.y,t.localScale.z},active=t.gameObject.activeSelf,prefabRoot=prefab==t.gameObject,prefabAsset=PrefabUtility.GetPrefabAssetPathOfNearestInstanceRoot(t),children=t.childCount};rows.Add(row);if(Korean(t.name))names.Add(new{scene=path,row});}if(rows.Any()){string file=Path.GetFileNameWithoutExtension(path);File.WriteAllText(dir+file+"_before.json",JsonConvert.SerializeObject(rows,Formatting.Indented));scenes.Add(new{path,objects=ts.Length,korean=ts.Count(t=>Korean(t.name))});if(ts.Any(t=>Korean(t.name))){string backup=dir+file+"_before.unity";if(File.Exists(backup))throw new Exception("Backup exists "+backup);EditorSceneManager.SaveScene(s,backup,true);}}}
  }finally{EditorSceneManager.RestoreSceneManagerSetup(setup);}File.WriteAllText(dir+"scene_names.json",JsonConvert.SerializeObject(names,Formatting.Indented));File.WriteAllText(dir+"scene_inventory.json",JsonConvert.SerializeObject(scenes,Formatting.Indented));return new{scenes,names=names.Count};}
}
